import re, json, unicodedata, itertools
from fractions import Fraction
from datetime import date

SYSTEMS = ["BRIGHTDESK", "LEDGR", "ATLAS", "VENDEX", "KOBO", "VERITAS"]
PLACEHOLDERS = {"", "n/a", "na", "-", "—", "–", "tbd", "?", "n/k", "none", "null", "unknown",
                "00/00/0000", "00.00.0000", "----/--/--", "0000-00-00"}


def is_blank(s):
    if s is None:
        return True
    t = str(s).strip().lower()
    return t in PLACEHOLDERS


def norm_txt(s):
    s = unicodedata.normalize("NFC", str(s or "")).lower()
    s = re.sub(r"[‒–—―−]", "-", s)
    return re.sub(r"\s+", " ", s).strip()


# ---------------------------------------------------------------- line parsing
def strip_free_text_vendex(body):
    return re.split(r"\s+(?:Remarks?|Notes?|Memo)\s*:", body, maxsplit=1, flags=re.I)[0].strip()


def parse_line(line):
    line = line.strip()
    if not line:
        return None
    m = re.match(r"^\s*([A-Za-z]+)", line)
    head = m.group(1).upper() if m else ""
    sysname = None
    for s in SYSTEMS:
        if head.startswith(s):
            sysname = s
    if sysname is None:
        return {"system": "UNKNOWN", "row": None, "fields": {}, "line": line}
    f = {}
    row = None
    if sysname == "BRIGHTDESK":
        parts = [p.strip() for p in line.split("|")]
        m = re.search(r"row\s*=\s*(\d+)", parts[0])
        row = int(m.group(1)) if m else None
        for p in parts[1:]:
            if "=" in p:
                k, v = p.split("=", 1)
                k = k.strip().lower()
                if k == "memo":
                    continue
                f[k] = v.strip()
    elif sysname == "LEDGR":
        parts = [p.strip() for p in line.split(";")]
        keys = ["sys", "row", "name", "anrede", "dob", "land", "telefon", "saldo", "status", "geaendert"]
        for i, p in enumerate(parts):
            if i < len(keys):
                f[keys[i]] = p
            else:
                f["extra%d" % i] = p
        row = int(re.sub(r"\D", "", f.get("row", "")) or 0) or None
        f.pop("sys", None)
        f.pop("row", None)
    elif sysname == "ATLAS":
        parts = [p.strip() for p in line.split("::")]
        m = re.search(r"#\s*(\d+)", parts[0])
        row = int(m.group(1)) if m else None
        rest = parts[1:]
        if rest:
            f["name"] = rest[0]
        tags = []
        for p in rest[1:]:
            lp = p.lower()
            if lp.startswith("born"):
                f["born"] = p[4:].strip()
            elif lp.startswith("tel"):
                f["tel"] = p[3:].strip()
            elif lp.startswith("owed"):
                f["owed"] = p[4:].strip()
            elif lp.startswith("last change"):
                f["last_change"] = p[len("last change"):].strip()
            elif lp.startswith("note") or lp.startswith("remark") or lp.startswith("memo"):
                continue
            elif "country" not in f:
                f["country"] = p
            else:
                tags.append(p)
        f["tag"] = " :: ".join(tags)
    elif sysname == "VENDEX":
        m = re.match(r"^\s*Vendex\s+#?(\d+)\s*[—–\-:]*\s*(.*)$", line, flags=re.I | re.S)
        row = int(m.group(1)) if m else None
        body = m.group(2) if m else line
        f["text"] = strip_free_text_vendex(body)
    elif sysname == "KOBO":
        parts = [p.strip() for p in line.split("|")]
        m = re.match(r"^KOBO\s*/\s*(\d+)\s*(.*)$", parts[0], flags=re.I)
        row = int(m.group(1)) if m else None
        first = m.group(2) if m else parts[0]
        for p in [first] + parts[1:]:
            if ":" in p:
                k, v = p.split(":", 1)
                k = k.strip().lower()
                if k in ("note", "memo", "remark"):
                    continue
                f[k] = v.strip()
    elif sysname == "VERITAS":
        j = line[line.index("{"):] if "{" in line else "{}"
        try:
            obj = json.loads(j)
        except Exception:
            obj = {}
        row = obj.get("row")
        try:
            row = int(row)
        except Exception:
            row = None
        for k, v in obj.items():
            if k in ("note", "memo", "remark"):
                continue
            f[k] = "" if v is None else (v if isinstance(v, str) else json.dumps(v))
        f["_obj_dob"] = obj.get("dob")
    return {"system": sysname, "row": row, "fields": f, "line": line}


# ---------------------------------------------------------------- dates
MONTHS = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6, "jul": 7, "aug": 8, "sep": 9,
          "oct": 10, "nov": 11, "dec": 12, "mär": 3, "mrz": 3, "okt": 10, "dez": 12, "mai": 5, "juni": 6, "juli": 7}
WORDNUM = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8,
           "ninth": 9, "tenth": 10, "eleventh": 11, "twelfth": 12}


def mk_date(y, m, d):
    try:
        return date(int(y), int(m), int(d)).isoformat()
    except Exception:
        return None


def fix_year(y, birth):
    y = int(y)
    if y < 100:
        if birth:
            return 1900 + y
        return 2000 + y if y < 70 else 1900 + y
    return y


def parse_date(s, order="DMY", birth=True):
    """Return ISO date or None."""
    if s is None:
        return None
    t = str(s).strip()
    if is_blank(t) or re.fullmatch(r"[0\W_]*", t):
        return None
    t = re.sub(r"[年月]", ".", t).replace("日", "").strip()
    tl = t.lower()
    # ISO / timestamp
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})", t)
    if m:
        return mk_date(*m.groups())
    # Japanese era
    m = re.match(r"^([SHRTM])\s*(\d{1,2})[./\-](\d{1,2})[./\-](\d{1,2})$", t, flags=re.I)
    if m:
        base = {"S": 1925, "H": 1988, "R": 2018, "T": 1911, "M": 1867}[m.group(1).upper()]
        return mk_date(base + int(m.group(2)), m.group(3), m.group(4))
    # month names
    mm = None
    for w in re.findall(r"[a-zäöü]+", tl):
        k = w[:3]
        if w[:4] in MONTHS:
            k = w[:4]
        if k in MONTHS and (len(w) >= 3):
            if w in ("mar", "march", "mär", "märz", "mrz") or w.startswith(k):
                mm = MONTHS[k]
                break
    if mm is not None:
        nums = re.findall(r"\d+", tl)
        if not nums:
            return None
        y = None
        d = None
        big = [n for n in nums if len(n) == 4]
        if big:
            y = int(big[0])
            rest = [n for n in nums if n != big[0]]
            d = int(rest[0]) if rest else None
        elif len(nums) >= 2:
            # e.g. 21-Aug-74 -> day first, year last
            d = int(nums[0])
            y = fix_year(nums[-1], birth)
        if d is None:
            for w, v in WORDNUM.items():
                if w in tl:
                    d = v
        if y is None or d is None:
            return None
        return mk_date(y, mm, d)
    nums = re.findall(r"\d+", t)
    if len(nums) == 3:
        a, b, c = nums
        if len(a) == 4:
            return mk_date(a, b, c)
        y = fix_year(c, birth)
        if order == "MDY":
            return mk_date(y, a, b)
        if order == "YMD":
            return mk_date(fix_year(a, birth), b, c)
        return mk_date(y, b, a)
    if len(nums) == 1 and len(nums[0]) == 8:
        n = nums[0]
        return mk_date(n[:4], n[4:6], n[6:])
    return None


# ---------------------------------------------------------------- numbers / money
ONES = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8,
        "nine": 9, "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15,
        "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19, "twenty": 20, "thirty": 30, "forty": 40,
        "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90, "a": 1}
SCALES = {"hundred": 100, "thousand": 1000, "million": 1000000}


def words_to_int(words):
    total = 0
    cur = 0
    seen = False
    for w in words:
        if w in ONES:
            cur += ONES[w]
            seen = True
        elif w == "hundred":
            cur = (cur or 1) * 100
            seen = True
        elif w in ("thousand", "million"):
            total += (cur or 1) * SCALES[w]
            cur = 0
            seen = True
        elif w == "and":
            continue
        else:
            return None
    return (total + cur) if seen else None


def num_from_text(t, german=False):
    m = re.search(r"\d[\d.,'\s]*\d|\d", t)
    if not m:
        return None
    s = re.sub(r"[\s']", "", m.group(0))
    if german:
        s = s.replace(".", "").replace(",", ".")
    else:
        if re.fullmatch(r"\d{1,3}(\.\d{3})+,\d{1,2}", s) or re.fullmatch(r"\d+,\d{1,2}", s):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return Fraction(s)
    except Exception:
        return None


CUR_SYMS = [("€", "EUR"), ("£", "GBP"), ("¥", "JPY"), ("円", "JPY"), ("$", "USD")]


def parse_money(s, default_ccy, german=False, cr_negative=False):
    """returns (Fraction amount with printed sign, ccy) or None"""
    if s is None:
        return None
    t = str(s).strip()
    if is_blank(t):
        return None
    neg = False
    tt = t
    if "(" in tt and ")" in tt:
        neg = True
    if re.search(r"^\s*[-−]", tt) or re.search(r"[-−]\s*$", tt) or re.search(r"[-−]\s*[€£¥$]", tt) \
            or re.search(r"[A-Z]{3}\s*[-−]\s*\d", tt) or re.search(r"\d\s*[-−]\s*(?:[A-Z]{3}|[€£¥$円])", tt):
        neg = True
    if "▲" in tt or "△" in tt:
        neg = True
    if cr_negative and re.search(r"\bCR\b", tt, flags=re.I):
        neg = True
    ccy = None
    m = re.search(r"\b(USD|EUR|GBP|JPY|CHF|CAD|AUD|SEK|DKK|NOK|MXN)\b", tt.upper())
    if m:
        ccy = m.group(1)
    else:
        for sym, c in CUR_SYMS:
            if sym in tt:
                ccy = c
                break
    if ccy is None:
        ccy = default_ccy
    v = num_from_text(tt, german=german)
    if v is None:
        return None
    return (-v if neg else v, ccy)


def parse_rates(spec):
    rates = {}
    for a, b, x in re.findall(r"\b([A-Z]{3})\s*/\s*([A-Z]{3})\s+([0-9]+(?:\.[0-9]+)?)", spec):
        x = Fraction(x)
        if b == "USD":
            rates[a] = x
        elif a == "USD":
            rates[b] = 1 / x
    rates["USD"] = Fraction(1)
    return rates


def round_half_away(x):
    q = abs(x) * 100
    n = int(q)
    if q - n >= Fraction(1, 2):
        n += 1
    v = n / 100
    return -v if x < 0 else v


# ---------------------------------------------------------------- phones
DEFAULT_CC = {"US": ("1", ""), "CA": ("1", ""), "GB": ("44", "0"), "IE": ("353", "0"), "AU": ("61", "0"),
              "DE": ("49", "0"), "AT": ("43", "0"), "CH": ("41", "0"), "FR": ("33", "0"), "BE": ("32", "0"),
              "ES": ("34", ""), "MX": ("52", ""), "IT": ("39", ""), "NL": ("31", "0"), "JP": ("81", "0"),
              "SE": ("46", "0"), "DK": ("45", ""), "NO": ("47", ""), "NZ": ("64", "0"), "FI": ("358", "0"),
              "PT": ("351", ""), "PL": ("48", ""), "LU": ("352", ""), "IS": ("354", ""), "GR": ("30", ""),
              "BR": ("55", "0"), "IN": ("91", "0"), "CN": ("86", "0"), "KR": ("82", "0"), "ZA": ("27", "0"),
              "SG": ("65", ""), "CZ": ("420", ""), "HU": ("36", "06"), "TR": ("90", "0"), "AR": ("54", "0")}


def parse_cc_table(spec):
    t = dict(DEFAULT_CC)
    for iso, cc, rest in re.findall(r"^\s*[A-Za-z][A-Za-z .]*?\s{2,}([A-Z]{2})\s+\+(\d{1,4})\s+trunk prefix:\s*([^\n]*)", spec, flags=re.M):
        r = rest.strip().lower()
        trunk = ""
        m = re.match(r"(\d+)", r)
        if m:
            trunk = m.group(1)
        t[iso] = (cc, trunk)
    return t


def normalize_phone(raw, country, system, cctab, force_intl=False):
    if raw is None:
        return None
    s = str(raw).strip()
    if is_blank(s):
        return None
    digits = re.sub(r"\D", "", s)
    if not digits or set(digits) == {"0"}:
        return None
    rest = None
    if force_intl or s.startswith("+"):
        rest = digits
    elif digits.startswith("00"):
        rest = digits[2:]
    elif system == "BRIGHTDESK" and digits.startswith("011"):
        rest = digits[3:]
    if rest is not None:
        ccs = {}
        for iso, (cc, trunk) in cctab.items():
            ccs.setdefault(cc, trunk)
        cc = None
        for L in (1, 2, 3):
            if rest[:L] in ccs:
                cc = rest[:L]
                break
        if cc is None:
            return "+" + rest
        nat = rest[len(cc):]
        trunk = ccs[cc]
        if trunk and nat.startswith(trunk) and cc not in ("39",):
            nat = nat[len(trunk):]
        if not nat:
            return None
        return "+" + cc + nat
    if not country or country not in cctab:
        return None
    cc, trunk = cctab[country]
    nat = digits
    if trunk and nat.startswith(trunk):
        nat = nat[len(trunk):]
    if cc == "1" and len(nat) == 11 and nat.startswith("1"):
        nat = nat[1:]
    if not nat:
        return None
    return "+" + cc + nat


# ---------------------------------------------------------------- countries
COUNTRY_ALIASES = {
    "US": ["us", "usa", "u s", "u s a", "united states", "united states of america", "america", "vereinigte staaten",
           "vereinigte staaten von amerika", "amerika", "estados unidos", "etats unis"],
    "CA": ["ca", "can", "canada", "kanada"],
    "GB": ["gb", "uk", "u k", "gbr", "united kingdom", "great britain", "britain", "england", "scotland", "wales",
           "vereinigtes königreich", "grossbritannien", "großbritannien", "england uk"],
    "IE": ["ie", "irl", "ireland", "irland", "eire", "éire", "republic of ireland"],
