    "LU": ["lu", "lux", "luxembourg", "luxemburg"],
}
ALIAS2ISO = {}
for _iso, _names in COUNTRY_ALIASES.items():
    for _n in _names:
        ALIAS2ISO[_n] = _iso


def ckey(s):
    s = norm_txt(s)
    s = re.sub(r"[.\-_,()]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def country_lookup(raw):
    if is_blank(raw):
        return None
    k = ckey(raw)
    if k in ALIAS2ISO:
        return ALIAS2ISO[k]
    return None


def country_fuzzy(raw):
    k = ckey(raw)
    if len(k) < 5:
        return None
    best = None
    for alias, iso in ALIAS2ISO.items():
        if len(alias) < 5:
            continue
        d = osa(k, alias)
        if d <= 2 and (best is None or d < best[0]):
            best = (d, iso)
    return best[1] if best else None


# ---------------------------------------------------------------- names
TITLES = {"mr", "mrs", "ms", "miss", "mx", "dr", "prof", "professor", "sir", "dame", "herr", "frau", "rev", "mme",
          "mlle", "madame", "monsieur", "sr", "sra", "don", "dona", "doña", "lord", "lady", "fr", "phd", "md", "jr"}


PARTICLES = {"van", "von", "de", "der", "den", "da", "di", "del", "della", "des", "du", "le", "la", "ter", "ten",
             "op", "het", "dos", "das", "af", "zu", "vom", "y"}


def is_title(tok):
    return tok.lower().strip(".,") in TITLES


def is_initial(tok):
    t = tok.strip(".,")
    return len(t) == 1 and t.isalpha()


def clean_tokens(s):
    s = re.sub(r"\([^)]*\)", " ", s or "")
    toks = [t for t in re.split(r"\s+", s.strip()) if t]
    return [t.strip(",") for t in toks if not is_title(t)]


def split_comma(s):
    fam, giv = s.split(",", 1)
    ft = clean_tokens(fam)
    gt = [t for t in clean_tokens(giv) if not is_initial(t)]
    return " ".join(gt), " ".join(ft)


def split_given_first(s, caps_family=False):
    toks = clean_tokens(s)
    toks_ni = [t for t in toks if not is_initial(t)]
    if not toks_ni:
        return "", ""
    if caps_family:
        fam = []
        i = len(toks) - 1
        while i >= 0 and not is_initial(toks[i]) and toks[i].upper() == toks[i] and re.search(r"[A-Za-zÀ-ÿ]", toks[i]):
            fam.insert(0, toks[i])
            i -= 1
        if fam and i >= 0:
            giv = [t for t in toks[:i + 1] if not is_initial(t)]
            while len(giv) > 1 and giv[-1].lower() in PARTICLES:
                fam.insert(0, giv.pop())
            if giv:
                return " ".join(giv), " ".join(fam)
    if len(toks_ni) == 1:
        return toks_ni[0], ""
    return toks_ni[0], " ".join(toks_ni[1:])


def row_name(system, f):
    if system == "BRIGHTDESK":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "LEDGR":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "ATLAS":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "KOBO":
        n = f.get("member", "")
        toks = clean_tokens(n)
        if "," in n:
            return split_comma(n)
        if len(toks) >= 2:
            return " ".join(t for t in toks[1:] if not is_initial(t)), toks[0]
        return (toks[0] if toks else ""), ""
    if system == "VERITAS":
        g = " ".join(t for t in clean_tokens(f.get("given", "")) if not is_initial(t))
        return g, " ".join(clean_tokens(f.get("family", "")))
    return "", ""


ACCENT_MAP = {"ä": ["a", "ae"], "ö": ["o", "oe"], "ü": ["u", "ue"], "ß": ["ss"], "ø": ["o", "oe"], "å": ["a", "aa"],
              "æ": ["ae"], "ō": ["o", "ou"], "ū": ["u", "uu"], "œ": ["oe"], "đ": ["d"], "ł": ["l"], "ı": ["i"], "þ": ["th"]}


def char_opts(c):
    if c in ACCENT_MAP:
        return ACCENT_MAP[c]
    d = unicodedata.normalize("NFD", c)
    b = "".join(x for x in d if not unicodedata.combining(x))
    return [b]


def variants(s):
    s = unicodedata.normalize("NFC", s.lower())
    opts = [char_opts(c) for c in s]
    out = [""]
    for o in opts:
        out = [p + x for p in out for x in o]
        if len(out) > 128:
            out = out[:128]
    return set(out)


def has_accent(s):
    return any(ord(c) > 127 for c in s)


def osa(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 2:
        return 3
    d = [[0] * (lb + 1) for _ in range(la + 1)]
    for i in range(la + 1):
        d[i][0] = i
    for j in range(lb + 1):
        d[0][j] = j
    for i in range(1, la + 1):
        for j in range(1, lb + 1):
            c = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[la][lb]


def name_key(s):
    return re.sub(r"[\s'’`´\.]", "", unicodedata.normalize("NFC", (s or "").lower()))


def min_dist(a, b):
    va, vb = variants(name_key(a)), variants(name_key(b))
    best = 9
    for x in va:
        for y in vb:
            d = 0 if x == y else osa(x, y)
            if d < best:
                best = d
                if best == 0:
                    return 0
    return best


def parse_nicknames(spec):
    nick = {}
    m = re.search(r"Appendix A(.*)$", spec, flags=re.S | re.I)
    txt = m.group(1) if m else ""
    for lhs, formal in re.findall(r"([A-Za-zÀ-ÿĀ-ſ'/ ]+?)\s*=\s*([A-Za-zÀ-ÿĀ-ſ']+)", txt):
        for n in lhs.split("/"):
            n = n.strip()
            if n:
                nick[name_key(n)] = formal.strip()
    return nick


def formalize(given, nick):
    k = name_key(given)
    if k in nick:
        return nick[k]
    toks = given.split()
    if len(toks) > 1 and name_key(toks[0]) in nick:
        return " ".join([nick[name_key(toks[0])]] + toks[1:])
    return given


def section(notes, name):
    paras = re.split(r"\n\s*\n", notes or "")
    out = []
    for p in paras:
        ps = p.strip()
        if ps.upper().startswith(name.upper()):
            out.append(ps)
    return "\n\n".join(out)


def main(input):
    inp = input.get("inputs") or {}
    export = inp.get("export") or ""
    if isinstance(export, list):
        lines = [x if isinstance(x, str) else json.dumps(x) for x in export]
    else:
        lines = str(export).splitlines()
    rows = []
    for ln in lines:
        r = parse_line(ln)
        if r is None or r["row"] is None or r["system"] == "UNKNOWN":
            continue
        rows.append(r)
    vrows = [r for r in rows if r["system"] == "VENDEX"]
    notes = inp.get("source_notes") or ""
    vnotes = section(notes, "General") + "\n\n" + section(notes, "VENDEX")
    batches = []
    B = 5
    for i in range(0, len(vrows), B):
        chunk = vrows[i:i + B]
        batches.append({
            "ids": [r["row"] for r in chunk],
            "entries": "\n".join("row %d: %s" % (r["row"], r["fields"]["text"]) for r in chunk),
            "notes": vnotes,
        })
    cstr = set()
    for r in rows:
        f = r["fields"]
        for k in ("country", "land"):
            v = f.get(k)
            if v is not None and not is_blank(v) and country_lookup(v) is None:
                cstr.add(v.strip())
    clist = sorted(cstr)
    return {
        "rows": rows,
        "vendex_batches": batches,
        "n_vendex": len(vrows),
        "country_strings": clist if clist else ["Deutschland"],
        "country_text": "\n".join(clist if clist else ["Deutschland"]),
    }

import re, json, unicodedata, itertools
from fractions import Fraction
from datetime import date

SYSTEMS = ["BRIGHTDESK", "LEDGR", "ATLAS", "VENDEX", "KOBO", "VERITAS"]
PLACEHOLDERS = {"", "n/a", "na", "-", "—", "–", "tbd", "?", "n/k", "none", "null", "unknown",
                "00/00/0000", "00.00.0000", "----/--/--", "0000-00-00"}


def is_blank(s):
    if s is None:
        return True
    t = str(s).strip().lower()
    return t in PLACEHOLDERS


def norm_txt(s):
    s = unicodedata.normalize("NFC", str(s or "")).lower()
    s = re.sub(r"[‒–—―−]", "-", s)
    return re.sub(r"\s+", " ", s).strip()


# ---------------------------------------------------------------- line parsing
def strip_free_text_vendex(body):
    return re.split(r"\s+(?:Remarks?|Notes?|Memo)\s*:", body, maxsplit=1, flags=re.I)[0].strip()


def parse_line(line):
    line = line.strip()
    if not line:
        return None
    m = re.match(r"^\s*([A-Za-z]+)", line)
    head = m.group(1).upper() if m else ""
    sysname = None
    for s in SYSTEMS:
        if head.startswith(s):
            sysname = s
    if sysname is None:
        return {"system": "UNKNOWN", "row": None, "fields": {}, "line": line}
    f = {}
    row = None
    if sysname == "BRIGHTDESK":
        parts = [p.strip() for p in line.split("|")]
        m = re.search(r"row\s*=\s*(\d+)", parts[0])
        row = int(m.group(1)) if m else None
        for p in parts[1:]:
            if "=" in p:
                k, v = p.split("=", 1)
                k = k.strip().lower()
                if k == "memo":
                    continue
                f[k] = v.strip()
    elif sysname == "LEDGR":
        parts = [p.strip() for p in line.split(";")]
        keys = ["sys", "row", "name", "anrede", "dob", "land", "telefon", "saldo", "status", "geaendert"]
        for i, p in enumerate(parts):
            if i < len(keys):
                f[keys[i]] = p
            else:
                f["extra%d" % i] = p
        row = int(re.sub(r"\D", "", f.get("row", "")) or 0) or None
        f.pop("sys", None)
        f.pop("row", None)
    elif sysname == "ATLAS":
        parts = [p.strip() for p in line.split("::")]
        m = re.search(r"#\s*(\d+)", parts[0])
        row = int(m.group(1)) if m else None
        rest = parts[1:]
        if rest:
            f["name"] = rest[0]
        tags = []
        for p in rest[1:]:
            lp = p.lower()
            if lp.startswith("born"):
                f["born"] = p[4:].strip()
            elif lp.startswith("tel"):
                f["tel"] = p[3:].strip()
            elif lp.startswith("owed"):
                f["owed"] = p[4:].strip()
            elif lp.startswith("last change"):
                f["last_change"] = p[len("last change"):].strip()
            elif lp.startswith("note") or lp.startswith("remark") or lp.startswith("memo"):
                continue
            elif "country" not in f:
                f["country"] = p
            else:
                tags.append(p)
        f["tag"] = " :: ".join(tags)
    elif sysname == "VENDEX":
        m = re.match(r"^\s*Vendex\s+#?(\d+)\s*[—–\-:]*\s*(.*)$", line, flags=re.I | re.S)
        row = int(m.group(1)) if m else None
        body = m.group(2) if m else line
        f["text"] = strip_free_text_vendex(body)
    elif sysname == "KOBO":
        parts = [p.strip() for p in line.split("|")]
        m = re.match(r"^KOBO\s*/\s*(\d+)\s*(.*)$", parts[0], flags=re.I)
        row = int(m.group(1)) if m else None
        first = m.group(2) if m else parts[0]
        for p in [first] + parts[1:]:
            if ":" in p:
                k, v = p.split(":", 1)
                k = k.strip().lower()
                if k in ("note", "memo", "remark"):
                    continue
                f[k] = v.strip()
    elif sysname == "VERITAS":
        j = line[line.index("{"):] if "{" in line else "{}"
        try:
            obj = json.loads(j)
        except Exception:
            obj = {}
        row = obj.get("row")
        try:
            row = int(row)
        except Exception:
            row = None
        for k, v in obj.items():
            if k in ("note", "memo", "remark"):
                continue
            f[k] = "" if v is None else (v if isinstance(v, str) else json.dumps(v))
        f["_obj_dob"] = obj.get("dob")
    return {"system": sysname, "row": row, "fields": f, "line": line}


# ---------------------------------------------------------------- dates
MONTHS = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6, "jul": 7, "aug": 8, "sep": 9,
          "oct": 10, "nov": 11, "dec": 12, "mär": 3, "mrz": 3, "okt": 10, "dez": 12, "mai": 5, "juni": 6, "juli": 7}
WORDNUM = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8,
           "ninth": 9, "tenth": 10, "eleventh": 11, "twelfth": 12}


def mk_date(y, m, d):
    try:
        return date(int(y), int(m), int(d)).isoformat()
    except Exception:
        return None


def fix_year(y, birth):
    y = int(y)
    if y < 100:
        if birth:
            return 1900 + y
        return 2000 + y if y < 70 else 1900 + y
    return y


def parse_date(s, order="DMY", birth=True):
    """Return ISO date or None."""
    if s is None:
        return None
    t = str(s).strip()
    if is_blank(t) or re.fullmatch(r"[0\W_]*", t):
        return None
    t = re.sub(r"[年月]", ".", t).replace("日", "").strip()
    tl = t.lower()
    # ISO / timestamp
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})", t)
    if m:
        return mk_date(*m.groups())
    # Japanese era
    m = re.match(r"^([SHRTM])\s*(\d{1,2})[./\-](\d{1,2})[./\-](\d{1,2})$", t, flags=re.I)
    if m:
        base = {"S": 1925, "H": 1988, "R": 2018, "T": 1911, "M": 1867}[m.group(1).upper()]
        return mk_date(base + int(m.group(2)), m.group(3), m.group(4))
    # month names
    mm = None
    for w in re.findall(r"[a-zäöü]+", tl):
        k = w[:3]
        if w[:4] in MONTHS:
            k = w[:4]
        if k in MONTHS and (len(w) >= 3):
            if w in ("mar", "march", "mär", "märz", "mrz") or w.startswith(k):
                mm = MONTHS[k]
                break
    if mm is not None:
        nums = re.findall(r"\d+", tl)
        if not nums:
            return None
        y = None
        d = None
        big = [n for n in nums if len(n) == 4]
        if big:
            y = int(big[0])
            rest = [n for n in nums if n != big[0]]
            d = int(rest[0]) if rest else None
        elif len(nums) >= 2:
            # e.g. 21-Aug-74 -> day first, year last
            d = int(nums[0])
            y = fix_year(nums[-1], birth)
        if d is None:
            for w, v in WORDNUM.items():
                if w in tl:
                    d = v
        if y is None or d is None:
            return None
        return mk_date(y, mm, d)
    nums = re.findall(r"\d+", t)
    if len(nums) == 3:
        a, b, c = nums
        if len(a) == 4:
            return mk_date(a, b, c)
        y = fix_year(c, birth)
        if order == "MDY":
            return mk_date(y, a, b)
        if order == "YMD":
            return mk_date(fix_year(a, birth), b, c)
        return mk_date(y, b, a)
    if len(nums) == 1 and len(nums[0]) == 8:
        n = nums[0]
        return mk_date(n[:4], n[4:6], n[6:])
    return None


# ---------------------------------------------------------------- numbers / money
ONES = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8,
        "nine": 9, "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15,
        "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19, "twenty": 20, "thirty": 30, "forty": 40,
        "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90, "a": 1}
SCALES = {"hundred": 100, "thousand": 1000, "million": 1000000}


def words_to_int(words):
    total = 0
    cur = 0
    seen = False
    for w in words:
        if w in ONES:
            cur += ONES[w]
            seen = True
        elif w == "hundred":
            cur = (cur or 1) * 100
            seen = True
        elif w in ("thousand", "million"):
            total += (cur or 1) * SCALES[w]
            cur = 0
            seen = True
        elif w == "and":
            continue
        else:
            return None
    return (total + cur) if seen else None


def num_from_text(t, german=False):
    m = re.search(r"\d[\d.,'\s]*\d|\d", t)
    if not m:
        return None
    s = re.sub(r"[\s']", "", m.group(0))
    if german:
        s = s.replace(".", "").replace(",", ".")
    else:
        if re.fullmatch(r"\d{1,3}(\.\d{3})+,\d{1,2}", s) or re.fullmatch(r"\d+,\d{1,2}", s):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    try:
        return Fraction(s)
    except Exception:
        return None


CUR_SYMS = [("€", "EUR"), ("£", "GBP"), ("¥", "JPY"), ("円", "JPY"), ("$", "USD")]


def parse_money(s, default_ccy, german=False, cr_negative=False):
    """returns (Fraction amount with printed sign, ccy) or None"""
    if s is None:
        return None
    t = str(s).strip()
    if is_blank(t):
        return None
    neg = False
    tt = t
    if "(" in tt and ")" in tt:
        neg = True
    if re.search(r"^\s*[-−]", tt) or re.search(r"[-−]\s*$", tt) or re.search(r"[-−]\s*[€£¥$]", tt) \
            or re.search(r"[A-Z]{3}\s*[-−]\s*\d", tt) or re.search(r"\d\s*[-−]\s*(?:[A-Z]{3}|[€£¥$円])", tt):
        neg = True
    if "▲" in tt or "△" in tt:
        neg = True
    if cr_negative and re.search(r"\bCR\b", tt, flags=re.I):
        neg = True
    ccy = None
    m = re.search(r"\b(USD|EUR|GBP|JPY|CHF|CAD|AUD|SEK|DKK|NOK|MXN)\b", tt.upper())
    if m:
        ccy = m.group(1)
    else:
        for sym, c in CUR_SYMS:
            if sym in tt:
                ccy = c
                break
    if ccy is None:
        ccy = default_ccy
    v = num_from_text(tt, german=german)
    if v is None:
        return None
    return (-v if neg else v, ccy)


def parse_rates(spec):
    rates = {}
    for a, b, x in re.findall(r"\b([A-Z]{3})\s*/\s*([A-Z]{3})\s+([0-9]+(?:\.[0-9]+)?)", spec):
        x = Fraction(x)
        if b == "USD":
            rates[a] = x
        elif a == "USD":
            rates[b] = 1 / x
    rates["USD"] = Fraction(1)
    return rates


def round_half_away(x):
    q = abs(x) * 100
    n = int(q)
    if q - n >= Fraction(1, 2):
        n += 1
    v = n / 100
    return -v if x < 0 else v


