def parse_cc_table(spec):
    t = dict(DEFAULT_CC)
    for iso, cc, rest in re.findall(r"^\s*[A-Za-z][A-Za-z .]*?\s{2,}([A-Z]{2})\s+\+(\d{1,4})\s+trunk prefix:\s*([^\n]*)", spec, flags=re.M):
        r = rest.strip().lower()
        trunk = ""
        m = re.match(r"(\d+)", r)
        if m:
            trunk = m.group(1)
        t[iso] = (cc, trunk)
    return t


def normalize_phone(raw, country, system, cctab, force_intl=False):
    if raw is None:
        return None
    s = str(raw).strip()
    if is_blank(s):
        return None
    digits = re.sub(r"\D", "", s)
    if not digits or set(digits) == {"0"}:
        return None
    rest = None
    if force_intl or s.startswith("+"):
        rest = digits
    elif digits.startswith("00"):
        rest = digits[2:]
    elif system == "BRIGHTDESK" and digits.startswith("011"):
        rest = digits[3:]
    if rest is not None:
        ccs = {}
        for iso, (cc, trunk) in cctab.items():
            ccs.setdefault(cc, trunk)
        cc = None
        for L in (1, 2, 3):
            if rest[:L] in ccs:
                cc = rest[:L]
                break
        if cc is None:
            return "+" + rest
        nat = rest[len(cc):]
        trunk = ccs[cc]
        if trunk and nat.startswith(trunk) and cc not in ("39",):
            nat = nat[len(trunk):]
        if not nat:
            return None
        return "+" + cc + nat
    if not country or country not in cctab:
        return None
    cc, trunk = cctab[country]
    nat = digits
    if trunk and nat.startswith(trunk):
        nat = nat[len(trunk):]
    if cc == "1" and len(nat) == 11 and nat.startswith("1"):
        nat = nat[1:]
    if not nat:
        return None
    return "+" + cc + nat


