    for _n in _names:
        ALIAS2ISO[_n] = _iso


def ckey(s):
    s = norm_txt(s)
    s = re.sub(r"[.\-_,()]", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def country_lookup(raw):
    if is_blank(raw):
        return None
    k = ckey(raw)
    if k in ALIAS2ISO:
        return ALIAS2ISO[k]
    return None


def country_fuzzy(raw):
    k = ckey(raw)
    if len(k) < 5:
        return None
    best = None
    for alias, iso in ALIAS2ISO.items():
        if len(alias) < 5:
            continue
        d = osa(k, alias)
        if d <= 2 and (best is None or d < best[0]):
            best = (d, iso)
    return best[1] if best else None


# ---------------------------------------------------------------- names
TITLES = {"mr", "mrs", "ms", "miss", "mx", "dr", "prof", "professor", "sir", "dame", "herr", "frau", "rev", "mme",
          "mlle", "madame", "monsieur", "sr", "sra", "don", "dona", "doña", "lord", "lady", "fr", "phd", "md", "jr"}


PARTICLES = {"van", "von", "de", "der", "den", "da", "di", "del", "della", "des", "du", "le", "la", "ter", "ten",
             "op", "het", "dos", "das", "af", "zu", "vom", "y"}


def is_title(tok):
    return tok.lower().strip(".,") in TITLES


def is_initial(tok):
    t = tok.strip(".,")
    return len(t) == 1 and t.isalpha()


def clean_tokens(s):
    s = re.sub(r"\([^)]*\)", " ", s or "")
    toks = [t for t in re.split(r"\s+", s.strip()) if t]
    return [t.strip(",") for t in toks if not is_title(t)]


def split_comma(s):
    fam, giv = s.split(",", 1)
    ft = clean_tokens(fam)
    gt = [t for t in clean_tokens(giv) if not is_initial(t)]
    return " ".join(gt), " ".join(ft)


def split_given_first(s, caps_family=False):
    toks = clean_tokens(s)
    toks_ni = [t for t in toks if not is_initial(t)]
    if not toks_ni:
        return "", ""
    if caps_family:
        fam = []
        i = len(toks) - 1
        while i >= 0 and not is_initial(toks[i]) and toks[i].upper() == toks[i] and re.search(r"[A-Za-zÀ-ÿ]", toks[i]):
            fam.insert(0, toks[i])
            i -= 1
        if fam and i >= 0:
            giv = [t for t in toks[:i + 1] if not is_initial(t)]
            while len(giv) > 1 and giv[-1].lower() in PARTICLES:
                fam.insert(0, giv.pop())
            if giv:
                return " ".join(giv), " ".join(fam)
    if len(toks_ni) == 1:
        return toks_ni[0], ""
    return toks_ni[0], " ".join(toks_ni[1:])


def row_name(system, f):
    if system == "BRIGHTDESK":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "LEDGR":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "ATLAS":
        n = f.get("name", "")
        if "," in n:
            return split_comma(n)
        return split_given_first(n, caps_family=True)
    if system == "KOBO":
        n = f.get("member", "")
        toks = clean_tokens(n)
        if "," in n:
            return split_comma(n)
        if len(toks) >= 2:
            return " ".join(t for t in toks[1:] if not is_initial(t)), toks[0]
        return (toks[0] if toks else ""), ""
    if system == "VERITAS":
        g = " ".join(t for t in clean_tokens(f.get("given", "")) if not is_initial(t))
        return g, " ".join(clean_tokens(f.get("family", "")))
    return "", ""


ACCENT_MAP = {"ä": ["a", "ae"], "ö": ["o", "oe"], "ü": ["u", "ue"], "ß": ["ss"], "ø": ["o", "oe"], "å": ["a", "aa"],
              "æ": ["ae"], "ō": ["o", "ou"], "ū": ["u", "uu"], "œ": ["oe"], "đ": ["d"], "ł": ["l"], "ı": ["i"], "þ": ["th"]}


def char_opts(c):
    if c in ACCENT_MAP:
        return ACCENT_MAP[c]
    d = unicodedata.normalize("NFD", c)
    b = "".join(x for x in d if not unicodedata.combining(x))
    return [b]


def variants(s):
    s = unicodedata.normalize("NFC", s.lower())
    opts = [char_opts(c) for c in s]
    out = [""]
    for o in opts:
        out = [p + x for p in out for x in o]
        if len(out) > 128:
            out = out[:128]
    return set(out)


def has_accent(s):
    return any(ord(c) > 127 for c in s)


def osa(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 2:
        return 3
    d = [[0] * (lb + 1) for _ in range(la + 1)]
    for i in range(la + 1):
        d[i][0] = i
    for j in range(lb + 1):
        d[0][j] = j
    for i in range(1, la + 1):
        for j in range(1, lb + 1):
            c = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[la][lb]


def name_key(s):
    return re.sub(r"[\s'’`´\.]", "", unicodedata.normalize("NFC", (s or "").lower()))


def min_dist(a, b):
    va, vb = variants(name_key(a)), variants(name_key(b))
    best = 9
    for x in va:
        for y in vb:
            d = 0 if x == y else osa(x, y)
            if d < best:
                best = d
                if best == 0:
                    return 0
    return best


def parse_nicknames(spec):
    nick = {}
    m = re.search(r"Appendix A(.*)$", spec, flags=re.S | re.I)
    txt = m.group(1) if m else ""
    for lhs, formal in re.findall(r"([A-Za-zÀ-ÿĀ-ſ'/ ]+?)\s*=\s*([A-Za-zÀ-ÿĀ-ſ']+)", txt):
        for n in lhs.split("/"):
            n = n.strip()
            if n:
                nick[name_key(n)] = formal.strip()
    return nick


def formalize(given, nick):
    k = name_key(given)
    if k in nick:
        return nick[k]
    toks = given.split()
    if len(toks) > 1 and name_key(toks[0]) in nick:
        return " ".join([nick[name_key(toks[0])]] + toks[1:])
    return given


DEF_CCY = {"BRIGHTDESK": "USD", "LEDGR": "EUR", "ATLAS": "GBP", "KOBO": "JPY", "VERITAS": "USD", "VENDEX": "USD"}
DEF_ORDER = {"BRIGHTDESK": "MDY", "LEDGR": "DMY", "ATLAS": "DMY", "VENDEX": "MDY", "KOBO": "YMD", "VERITAS": "YMD"}
CUR_WORDS = {"dollar": "USD", "dollars": "USD", "usd": "USD", "euro": "EUR", "euros": "EUR", "eur": "EUR",
             "pound": "GBP", "pounds": "GBP", "gbp": "GBP", "sterling": "GBP", "yen": "JPY", "jpy": "JPY",
             "francs": "CHF", "franc": "CHF", "chf": "CHF", "cad": "CAD", "aud": "AUD", "sek": "SEK", "kronor": "SEK",
             "dkk": "DKK", "nok": "NOK", "mxn": "MXN", "pesos": "MXN", "peso": "MXN"}
QUALIFIERS = {"us", "u", "s", "american", "sterling", "british", "swiss", "australian", "canadian", "mexican"}
NUMWORDS = set(ONES) | {"hundred", "thousand", "million", "and"}


def words_amount(t):
    tl = norm_txt(t).replace("-", " ")
    toks = re.findall(r"[a-z]+", tl)
    idx = None
    for i, w in enumerate(toks):
        if w in CUR_WORDS and w not in ("sterling",):
            idx = i
            break
    if idx is None:
        return None
    j = idx - 1
    while j >= 0 and toks[j] in QUALIFIERS:
        j -= 1
    run = []
    while j >= 0 and toks[j] in NUMWORDS and toks[j] != "a":
        run.insert(0, toks[j])
        j -= 1
    if j >= 0 and toks[j] == "a":
        run.insert(0, "a")
    while run and run[0] == "and":
        run.pop(0)
    major = words_to_int(run) if run else None
    if major is None:
        return None
    minor = 0
    for k in range(idx + 1, len(toks)):
        if toks[k] in ("cents", "cent", "pence", "penny", "centimes", "rappen"):
            r2 = []
            m = k - 1
            while m > idx and toks[m] in NUMWORDS:
                r2.insert(0, toks[m])
                m -= 1
            while r2 and r2[0] == "and":
                r2.pop(0)
            minor = words_to_int(r2) or 0
            break
    return Fraction(major) + Fraction(minor, 100)


def vendex_ccy(t, model_ccy):
    tl = norm_txt(t)
    if "australian dollar" in tl:
        return "AUD"
    if "canadian dollar" in tl:
        return "CAD"
    m = re.search(r"\b(USD|EUR|GBP|JPY|CHF|CAD|AUD|SEK|DKK|NOK|MXN)\b", (t or "").upper())
    if m:
        return m.group(1)
    for sym, c in CUR_SYMS:
        if sym in (t or ""):
            return c
    for w in re.findall(r"[a-z]+", tl):
        if w in CUR_WORDS:
            return CUR_WORDS[w]
    mc = (model_ccy or "").strip().upper()
    return mc if re.fullmatch(r"[A-Z]{3}", mc) else None


def main(input):
    rows = input["parsed"]["rows"]
    cfg = input.get("config") or {}
    spec = (input.get("inputs") or {}).get("spec") or ""
    rates = parse_rates(spec)
    cctab = parse_cc_table(spec)
    nick = parse_nicknames(spec)

    syscfg = {}
    for s in cfg.get("systems") or []:
        syscfg[str(s.get("system", "")).upper()] = s

    def sc(system, key, default):
        v = syscfg.get(system, {}).get(key)
        return default if v in (None, "") else v

    # country map from model
    cmodel = {}
    for m in (input.get("countries") or {}).get("mappings") or []:
        iso = str(m.get("iso") or "").strip().upper()
        if re.fullmatch(r"[A-Z]{2}", iso):
            cmodel[ckey(m.get("text", ""))] = "GB" if iso == "UK" else iso

    def to_iso(raw):
        if is_blank(raw):
            return None
        c = country_lookup(raw)
        if c:
            return c
        k = ckey(raw)
        if k in cmodel:
            return cmodel[k]
        return country_fuzzy(raw)

    # vendex extraction results
    vex = {}
    for it in (input.get("vendex") or {}).get("items") or []:
        if not isinstance(it, dict):
            continue
        out = it.get("extract") or {}
        for r in out.get("rows") or []:
            try:
                vex[int(r.get("row"))] = r
            except Exception:
                pass

    rules = cfg.get("void_rules") or []

    def controlled_line(r):
        return " | ".join("%s=%s" % (k, v) for k, v in r["fields"].items() if not k.startswith("_"))

    def is_void(r):
        for rule in rules:
            if str(rule.get("system", "")).upper() != r["system"]:
                continue
            fld = str(rule.get("field", "")).lower().strip()
            op = str(rule.get("op", "contains")).lower()
            val = norm_txt(rule.get("value", ""))
            if not val:
                continue
            fields = {k.lower(): v for k, v in r["fields"].items()}
            if fld in fields:
                tv = norm_txt(fields[fld])
            else:
                tv = norm_txt(controlled_line(r))
                op = "contains"
            tvs = tv.rstrip(" .")
            vs = val.rstrip(" .")
            if op == "equals" and (tv == val or tvs == vs or val in [x.strip() for x in tv.split("::")]):
                return True
            if op == "startswith" and tv.startswith(val):
                return True
            if op == "endswith" and (tv.endswith(val) or tvs.endswith(vs)):
                return True
            if op == "contains" and val in tv:
                return True
        return False

    recs = []
    voided = []
    for r in rows:
        S = r["system"]
        f = r["fields"]
        if is_void(r):
            voided.append(r["row"])
            continue
        order = sc(S, "numeric_birth_date_order", DEF_ORDER.get(S, "DMY"))
        sign = -1 if sc(S, "printed_balance_sign", "same_as_master") == "opposite_to_master" else 1
        dccy = sc(S, "default_currency", DEF_CCY.get(S, "USD"))
        implicit = str(sc(S, "implicit_country", "") or "").upper() or None
        rec = {"row": r["row"], "system": S, "stale": bool(sc(S, "update_dates_unreliable", False))}
        country_raw = None
        phone_raw = None
        money = None
        force_intl = False
        if S == "VENDEX":
            v = vex.get(r["row"], {})
            g = " ".join(t for t in clean_tokens(v.get("given_name", "")) if not is_initial(t))
            fam = " ".join(clean_tokens(v.get("family_name", "")))
            rec["given"], rec["family"] = g, fam
            rec["dob"] = parse_date(v.get("birth_date_text"), order, True) or parse_date(v.get("birth_date_iso"), "YMD", True)
            rec["upd"] = parse_date(v.get("revision_date_text"), order, False) or parse_date(v.get("revision_date_iso"), "YMD", False)
            ci = str(v.get("country_iso") or "").strip().upper()
            rec["country"] = ("GB" if ci == "UK" else ci) if re.fullmatch(r"[A-Z]{2}", ci) else None
            phone_raw = v.get("phone_text")
            at = v.get("amount_text") or ""
            direction = str(v.get("direction") or "none")
            if direction != "none" and not is_blank(at):
                amt = None
                if re.search(r"\d", at):
                    amt = num_from_text(at)
                else:
                    amt = words_amount(at)
                if amt is None:
                    try:
                        amt = Fraction(str(v.get("amount_number")).replace(",", ""))
                    except Exception:
                        amt = None
                ccy = vendex_ccy(at, v.get("currency"))
                if amt is not None and ccy:
                    amt = abs(amt)
                    money = (-amt if direction == "credit" else amt, ccy)
        else:
            rec["given"], rec["family"] = row_name(S, f)
            if S == "BRIGHTDESK":
                rec["dob"] = parse_date(f.get("dob"), order, True)
                rec["upd"] = parse_date(f.get("updated"), order, False)
                country_raw = f.get("country")
                phone_raw = f.get("phone")
                money = parse_money(f.get("balance"), dccy)
            elif S == "LEDGR":
                rec["dob"] = parse_date(f.get("dob"), order, True)
                rec["upd"] = parse_date(f.get("geaendert"), order, False)
                country_raw = f.get("land")
                phone_raw = f.get("telefon")
                money = parse_money(f.get("saldo"), dccy, german=True)
            elif S == "ATLAS":
                rec["dob"] = parse_date(f.get("born"), order, True)
                rec["upd"] = parse_date(f.get("last_change"), order, False)
                country_raw = f.get("country")
                phone_raw = f.get("tel")
                money = parse_money(f.get("owed"), dccy, cr_negative=True)
            elif S == "KOBO":
                rec["dob"] = parse_date(f.get("birth"), "YMD", True)
                rec["upd"] = parse_date(f.get("upd"), "YMD", False)
                country_raw = f.get("country")
                phone_raw = f.get("tel")
                money = parse_money(f.get("balance"), dccy)
            elif S == "VERITAS":
                rec["dob"] = parse_date(f.get("dob"), "YMD", True)
                rec["upd"] = parse_date(f.get("ts"), "YMD", False)
                country_raw = f.get("country")
                phone_raw = f.get("msisdn")
                force_intl = True
                amt = f.get("amount")
                ccy = (f.get("ccy") or "").strip().upper() or dccy
                money = parse_money(amt, ccy) if not is_blank(amt) else None
                if money is not None:
                    money = (money[0], ccy)
            if money is not None:
                money = (money[0] * sign, money[1])
            rec["country"] = to_iso(country_raw) or implicit
        if rec.get("dob") == "1900-01-01":
            rec["dob"] = None
        rec["phone"] = normalize_phone(phone_raw, rec["country"], S, cctab, force_intl=force_intl)
        if money is not None and money[1] in rates:
            rec["usd"] = round_half_away(money[0] * rates[money[1]])
        else:
            rec["usd"] = None
        rec["gkey"] = formalize(rec["given"], nick)
        recs.append(rec)

    # identity
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(n):
        a = recs[i]
        if not a["family"] and not a["given"]:
            continue
        for j in range(i + 1, n):
            b = recs[j]
            if a["dob"] and b["dob"]:
                if a["dob"] != b["dob"]:
                    continue
            else:
                if not (a["phone"] and b["phone"] and a["phone"] == b["phone"]):
                    continue
            dg = min_dist(a["gkey"], b["gkey"])
            if dg > 1:
                continue
            if dg + min_dist(a["family"], b["family"]) <= 1:
                parent[find(i)] = find(j)

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(recs[i])

    def okey(r):
        u = r["upd"] or "0000-00-00"
        return (1 if r["stale"] else 0, "".join(chr(255 - ord(c)) for c in u))

    def nice(s):
        return s.title() if s.isupper() else s

    out = []
    for g in groups.values():
        g = sorted(g, key=okey)
        top = g[0]

        def pick_name(val, getter):
            if has_accent(val):
                return val
            k = name_key(val)
            for o in g:
                c = getter(o)
                if c and has_accent(c) and k in variants(name_key(c)):
                    return c
            return val

        given = pick_name(top["gkey"], lambda o: o["gkey"])
        family = pick_name(top["family"], lambda o: o["family"])

        def first(key):
            for o in g:
                if o.get(key) is not None:
                    return o[key]
            return None

        rows_ = sorted(o["row"] for o in g)
        out.append({
            "entity_id": rows_[0],
            "source_rows": rows_,
            "given_name": nice(given),
            "family_name": nice(family),
            "birth_date": first("dob"),
            "country": first("country"),
            "phone_e164": first("phone"),
            "amount_usd": (float(first("usd")) if first("usd") is not None else None),
        })
    out.sort(key=lambda r: r["entity_id"])
    return {"records": out, "voided": sorted(voided),
            "debug": [{k: (str(v) if isinstance(v, Fraction) else v) for k, v in r.items()} for r in recs]}

export default function main({subject}) {
  const reasons = []; const seen = new Set();
  for (const r of subject.records || []) {
    if (r.entity_id !== Math.min(...r.source_rows)) reasons.push('entity_id ' + r.entity_id);
    for (const x of r.source_rows) { if (seen.has(x)) reasons.push('dup row ' + x); seen.add(x); }
    if (r.birth_date !== null && !/^\d{4}-\d{2}-\d{2}$/.test(r.birth_date)) reasons.push('dob ' + r.entity_id);
    if (r.phone_e164 !== null && !/^\+\d{6,15}$/.test(r.phone_e164)) reasons.push('phone ' + r.entity_id);
    if (r.country !== null && !/^[A-Z]{2}$/.test(r.country)) reasons.push('country ' + r.entity_id);
  }
  return {pass: reasons.length === 0, score: reasons.length === 0 ? 1 : 0, reasons};
}
